"""Helpers for CSP-compatible HTML generated by server-side renderers."""

from __future__ import annotations

import hashlib
import re
from decimal import Decimal, InvalidOperation
from functools import lru_cache

from django.utils.html import format_html
from django.utils.safestring import mark_safe

from core.context import get_current_csp_nonce

_SAFE_COLOR = re.compile(r"^[0-9a-fA-F]{6}$")
_SAFE_LENGTH = re.compile(r"^(?:\d{1,3}(?:\.\d{1,3})?)(?:px|rem|em|pt|cm|mm|in)$", re.IGNORECASE)
_SAFE_NONCE = re.compile(r"^[A-Za-z0-9+/_=-]{1,256}$")


def status_color_class(color: str | None) -> tuple[str, str]:
    """Return a deterministic class and nonce-authorized rule for a status color.

    Status colors are intentionally limited to six-digit hex values.  A missing
    or malformed value falls back to the neutral palette color.  The generated
    rule is empty outside a request carrying the CSP nonce; callers still get a
    stable class so the markup never needs an inline style attribute.
    """
    return _color_class("status-color", color, "--status-color")


def color_chip_class(color: str | None) -> tuple[str, str]:
    """Return a safe class and rule for a solid color chip."""
    return _color_class("color-chip", color, "background-color")


def status_tint_class(color: str | None) -> tuple[str, str]:
    """Return a safe class and rule for a tinted status detail chip."""
    normalized = safe_hex_color(color)
    digest = hashlib.sha256(f"status-tint:{normalized}".encode("ascii")).hexdigest()[:16]
    class_name = f"status-tint-{digest}"
    css = f"background-color:#{normalized}1a;color:#{normalized};border:1px solid #{normalized}33;"
    return class_name, _nonce_style_block(class_name, css)


def percentage_class(value, prefix: str = "percentage-width") -> tuple[str, str]:
    """Return a bounded percentage class and its nonce-authorized CSS rule."""
    try:
        numeric = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError):
        numeric = Decimal("0")
    if not numeric.is_finite():
        numeric = Decimal("0")
    numeric = max(Decimal("0"), min(Decimal("100"), numeric))
    normalized = format(numeric, "f")
    if "." in normalized:
        normalized = normalized.rstrip("0").rstrip(".")
    normalized = normalized or "0"
    digest = hashlib.sha256(f"{prefix}:{normalized}".encode("ascii")).hexdigest()[:16]
    class_name = f"{prefix}-{digest}"
    return class_name, _nonce_style_block(class_name, f"width:{normalized}%;")


def length_class(value, prefix: str = "safe-length", property_name: str = "height") -> tuple[str, str]:
    """Return a bounded class/rule for a fixed CSS length value."""
    normalized = str(value or "").strip().lower()
    if not _SAFE_LENGTH.fullmatch(normalized):
        normalized = "36px"
    numeric = Decimal(re.match(r"\d+(?:\.\d+)?", normalized).group(0))
    if numeric < Decimal("0.1") or numeric > Decimal("200"):
        normalized = "36px"
    digest = hashlib.sha256(f"{prefix}:{property_name}:{normalized}".encode("ascii")).hexdigest()[:16]
    class_name = f"{prefix}-{digest}"
    return class_name, _nonce_style_block(class_name, f"{property_name}:{normalized};")


def safe_hex_color(color: str | None, fallback: str = "6c757d") -> str:
    normalized = str(color or "").lstrip("#")
    if re.fullmatch(r"[0-9a-fA-F]{3}", normalized):
        normalized = "".join(character * 2 for character in normalized)
    if not _SAFE_COLOR.fullmatch(normalized):
        normalized = fallback
    return normalized.lower()


@lru_cache(maxsize=512)
def _color_class_name(prefix: str, normalized: str, css_property: str) -> str:
    digest = hashlib.sha256(f"{css_property}:{normalized}".encode("ascii")).hexdigest()[:16]
    return f"{prefix}-{digest}"


def _color_class(prefix: str, color: str | None, css_property: str) -> tuple[str, str]:
    normalized = safe_hex_color(color)
    class_name = _color_class_name(prefix, normalized, css_property)

    return class_name, _nonce_style_block(class_name, f"{css_property}:#{normalized};")


@lru_cache(maxsize=1024)
def _render_style_block(nonce: str, class_name: str, declarations: str):
    return format_html('<style nonce="{}">.{}{{{}}}</style>', nonce, class_name, declarations)


def _nonce_style_block(class_name: str, declarations: str):
    nonce = get_current_csp_nonce()
    if not nonce or not _SAFE_NONCE.fullmatch(nonce):
        return mark_safe("")

    # A page repeats the same few colors on every row; the rendered block only
    # depends on (nonce, class, declarations), all plain strings.
    return _render_style_block(nonce, class_name, declarations)
